"""Home simplification checks."""
import sys
from playwright.sync_api import sync_playwright
BASE="http://127.0.0.1:8137"; results=[]; failures=[]
def ok(n,c): results.append(("PASS " if c else "FAIL ")+n); failures.append(n) if not c else None
with sync_playwright() as pw:
    try: b=pw.chromium.launch(channel="chrome")
    except Exception: b=pw.chromium.launch()
    p=b.new_page(viewport={"width":1440,"height":900}); errs=[]
    p.on("pageerror",lambda e: errs.append(str(e))); p.on("console",lambda m: errs.append(m.text) if m.type=="error" else None)
    r=p.goto(BASE+"/",wait_until="networkidle"); p.wait_for_timeout(300)
    ok("home 200",r.status==200); ok("home H1","more than a result" in p.locator("h1").text_content())
    ok("hero governance map",p.locator("object.hero-map").count()==1)
    ok("hero shares menu surface",p.locator(".hero").evaluate("e=>getComputedStyle(e).backgroundColor")=="rgb(247, 242, 232)")
    ok("hero mesh layer","hero-mesh.svg" in p.locator(".hero").evaluate("e=>getComputedStyle(e,'::before').backgroundImage"))
    ok("hero ink text",p.locator(".hero h1").evaluate("e=>getComputedStyle(e).color")=="rgb(10, 20, 32)")
    ok("hero map untouched",p.locator("object.hero-map").get_attribute("data")=="/assets/arqux-governance-side-en.svg")
    ok("hero map feathered","linear-gradient" in p.locator(".hero-visual").evaluate("e=>getComputedStyle(e).maskImage"))
    ok("hero map rounded",p.locator(".hero-map").evaluate("e=>getComputedStyle(e).borderRadius")=="28px")
    ok("mobile governance map",p.locator(".hero-mobile-map a").count()==6)
    svgs=[f for f in p.frames if "arqux-governance" in f.url]
    ok("svg map loaded",len(svgs)==1)
    if svgs:
        ok("six svg dimensions",svgs[0].locator(".arqx-stage").count()==6)
        ok("even ring arcs",svgs[0].locator("#arqx-stage-identidad").get_attribute("transform")=="translate(321,112.5)" and svgs[0].locator("#arqx-stage-contexto").get_attribute("transform")=="translate(321,467.5)")
        ok("lift follows stage",svgs[0].locator(".lift-card[data-stage=identidad]").get_attribute("transform")=="translate(321,112.5)")
        import re
        svgs[0].wait_for_function("()=>document.querySelector('.arqx-stage.is-synced')",timeout=20000)
        rot=float(re.sub(r"[^0-9.\-]","",svgs[0].locator("#arqx-learning-orbit").evaluate("e=>e.style.transform") or "0"))
        synced=svgs[0].evaluate("()=>document.querySelector('.arqx-stage.is-synced').dataset.stage")
        ea={"ejecucion":0,"evidencia":60,"contexto":120,"contrato":180,"identidad":240,"decision":300}[synced]
        ok("orbit syncs card",abs(((rot-ea+540)%360)-180)<13)
        ok("core beats on sync",svgs[0].locator("#arqx-core.is-beat").count()==1)
        ok("map title",svgs[0].locator("#map-title").count()==1)
        ok("triad nodes",svgs[0].locator(".triad-node").count()==3)
        ok("triad cards clear feather",svgs[0].locator(".triad-detail[data-triad=harness]").get_attribute("transform")=="translate(250,360)" and svgs[0].locator(".triad-detail[data-triad=project]").get_attribute("transform")=="translate(750,360)")
        ok("no visible subtitles",svgs[0].locator(".stage-desc").count()==0)
        svgs[0].locator("#arqx-stage-identidad").hover(); p.wait_for_timeout(120)
        ok("lifted card",svgs[0].locator(".lift-card.is-on").count()==1)
        svgs[0].locator(".triad-node[data-triad=harness]").hover(); p.wait_for_timeout(120)
        ok("triad detail",svgs[0].locator(".triad-detail.is-on").count()==1)
    ok("no board/palette/rail",p.locator("#wsboard,.palette,.progress-rail").count()==0)
    ok("problem scene H2","The decision was made" in p.locator("#local h2").text_content())
    ok("problem two sessions",p.locator("#local .loss-session").count()==2 and p.locator("#local .loss-link").count()==1)
    ok("problem sessions side by side",abs(p.locator("#local .loss-session").first.bounding_box()["y"]-p.locator("#local .loss-session").last.bounding_box()["y"])<2)
    ok("problem no extra cards",p.locator("#local .loss-card,#local .loss-consequences").count()==0)
    ok("problem same reference","Project criterion" in p.locator("#local .loss-session--decided .loss-ref-label").text_content() and "Project criterion" in p.locator("#local .loss-session--next .loss-ref-label").text_content())
    ok("problem references aligned",abs(p.locator("#local .loss-session--decided .loss-ref").bounding_box()["y"]-p.locator("#local .loss-session--next .loss-ref").bounding_box()["y"])<2)
    ok("problem empty slot","Reference unavailable" in p.locator("#local .loss-ref-miss").text_content() and p.locator("#local .loss-ghost").count()==0)
    ok("problem link at ref level",abs(p.locator("#local .loss-link").bounding_box()["y"]+p.locator("#local .loss-link").bounding_box()["height"]/2-(p.locator("#local .loss-session--decided .loss-ref").bounding_box()["y"]+p.locator("#local .loss-session--decided .loss-ref").bounding_box()["height"]/2))<6)
    ok("problem link labeled","did not carry over" in p.locator("#local .loss-link").get_attribute("aria-label").lower())
    ok("problem decision kept","Decision established" in p.locator("#local .loss-session--decided .loss-status").text_content())
    ok("problem one close",p.locator("#local .loss-verdict,#local .loss-cost,#local .loss-bridge,#local .loss-seam,#local .loss-ghost,#local .loss-absent").count()==0)
    ok("problem no memory claim","memory" not in p.locator("#local").text_content().lower())
    ok("problem no external CTA",p.locator("#local a").count()==1 and p.locator("#local a").first.get_attribute("href")=="#loss-ref-ayer")
    ok("scene S0",p.locator("#local .loss-act").is_visible() and not p.locator("#local .loss-question").is_visible() and p.locator("#local .loss-ref-miss").is_visible())
    ok("S0 stakes present",p.locator("#local .loss-stakes-now").is_visible() and "have to explain" in p.locator("#local .loss-stakes-now").text_content())
    p.locator("#local .loss-act").click()
    ok("S1 instant",p.locator("#local .loss-question").is_visible() and p.locator("#local .loss-give").is_visible() and not p.locator("#local .loss-act").is_visible())
    ok("S1 focus on question",p.locator("#local .loss-question").evaluate("e=>e===document.activeElement"))
    ok("S1 goto visible",p.locator("#local .loss-goto").is_visible())
    ok("S1 no lock",p.locator("#local .loss-give").evaluate("e=>!e.disabled"))
    p.wait_for_timeout(1000)
    p.locator("#local .loss-give").click()
    ok("S2 instant",p.locator("#local .loss-restored").is_visible() and not p.locator("#local .loss-ref-miss").is_visible())
    ok("S2 criterion exact",p.locator("#local .loss-restored .loss-quote").text_content()==p.locator("#local .loss-session--decided .loss-quote").text_content())
    ok("S2 ref solid",p.locator("#local .loss-session--next .loss-ref").evaluate("e=>getComputedStyle(e).borderLeftStyle")=="solid" and not p.locator("#local .loss-session--next .loss-ref").evaluate("e=>e.classList.contains('loss-ref--empty')") and p.locator("#local .loss-session--next .loss-ref").evaluate("e=>e.classList.contains('loss-ref--restored')"))
    ok("S2 question hidden",not p.locator("#local .loss-question").is_visible())
    ok("S2 manual trace",p.locator("#local .loss-link-manual").is_visible() and "manual" in p.locator("#local .loss-link-tag").text_content().lower())
    ok("S2 link label updated","manually" in p.locator("#local .loss-link").get_attribute("aria-label").lower())
    ok("S2 stakes past","had to explain" in p.locator("#local .loss-stakes-done").text_content() and p.locator("#local .loss-stakes-done").is_visible() and not p.locator("#local .loss-stakes-now").is_visible())
    ok("S2 focus on restored",p.locator("#local .loss-restored").evaluate("e=>e===document.activeElement"))
    ok("S2 announce",p.locator("#local .loss-announce").text_content().strip()!="")
    p.wait_for_timeout(600)
    p.locator("#local .loss-again").click()
    ok("scene reset",p.locator("#local .loss-act").is_visible() and p.locator("#local .loss-ref-miss").is_visible() and not p.locator("#local .loss-restored").is_visible() and p.locator("#local .loss-stakes-now").is_visible() and not p.locator("#local .loss-link-manual").is_visible())
    ok("reset focus",p.locator("#local .loss-act").evaluate("e=>e===document.activeElement"))
    ok("reset link label","did not carry over" in p.locator("#local .loss-link").get_attribute("aria-label").lower())
    ok("problem illustrative","Illustrative example" in p.locator("#local .loss-scene").text_content())
    ok("problem eyebrow","without shared context" in p.locator("#local .eyebrow").text_content())
    ok("problem human close","explain it again" in p.locator("#local .loss-stakes").text_content())
    ok("problem close prominent",float(p.locator("#local .loss-stakes").evaluate("e=>parseFloat(getComputedStyle(e).fontSize)"))>22)
    ok("problem break is amber","255, 181, 71" in p.locator("#local .loss-link-break").evaluate("e=>getComputedStyle(e).backgroundColor"))
    ok("failure is second section",p.locator("main > section").nth(1).get_attribute("id")=="failures")
    ok("failure five modes",p.locator("#failures .failure-case").count()==5)
    ok("failure coherence line",p.locator("#failures .coherence-line span").count()==1)
    ok("failure five distinct icons",len(set(p.locator("#failures .case-icon svg").evaluate_all("els=>els.map(e=>e.innerHTML)")))==5)
    ok("failure no dashed lines",p.locator("#failures .case-signal").count()==0)
    ok("failure five distinct icons",len(set(p.locator("#failures .case-icon svg").evaluate_all("els=>els.map(e=>e.innerHTML)")))==5)
    ok("failure large titles",p.locator("#failures .case-title b").first.evaluate("el=>parseFloat(getComputedStyle(el).fontSize)")>=16)
    ok("failure H2","five ordinary ways" in p.locator("#failures h2").text_content())
    ok("failure lead","context we have gained" in p.locator("#failures .failure-lead").text_content())
    ok("failure close","The output can survive" in p.locator("#failures .failure-close").text_content() and "not always" in p.locator("#failures .failure-close").text_content())
    ok("failure mechanisms",p.locator("#failures .case-mech").evaluate_all("els=>els.map(e=>e.textContent.trim())")==["Interpretation","Reconstruction","Compression","Transfer","Recovery"])
    ok("failure mechanism legible",p.locator("#failures .case-mech").first.evaluate("el=>parseFloat(getComputedStyle(el).fontSize)")>=12)
    ok("failure no links",p.locator("#failures a").count()==0 and p.locator("#failures .case-open").count()==5)
    ok("closure is last",p.locator("main > section").last.get_attribute("id")=="next")
    ok("closure single",p.locator("main > section").count()==4)
    ok("closure three routes",p.locator("#next .home-closure__route").count()==3)
    ok("closure no old case",p.locator("#anchors").count()==1 and p.locator(".flow-block,.source-panel").count()==0)
    ok("flat nav",p.locator(".nav-links a").count()==3)
    ok("no console errors",len(errs)==0)
    ctx=b.new_context(viewport={"width":320,"height":844}); q=ctx.new_page(); q.goto(BASE+"/es/",wait_until="networkidle")
    ok("ES mobile no overflow",q.evaluate("document.documentElement.scrollWidth-window.innerWidth")==0)
    ok("ES mobile hero surface",q.locator(".hero").evaluate("e=>getComputedStyle(e).backgroundColor")=="rgb(247, 242, 232)")
    ok("ES mobile hero lattice","repeating-linear-gradient" in q.locator(".hero").evaluate("e=>getComputedStyle(e,'::before').backgroundImage"))
    ok("ES mobile no mesh download","hero-mesh.svg" not in q.locator(".hero").evaluate("e=>getComputedStyle(e,'::before').backgroundImage"))
    ok("ES problem H2","La decisión se tomó" in q.locator("#local h2").text_content())
    ok("ES problem eyebrow","sin contexto compartido" in q.locator("#local .eyebrow").text_content())
    ok("ES empty slot","Referencia no disponible" in q.locator("#local .loss-ref-miss").text_content())
    ok("ES same reference","Criterio del proyecto" in q.locator("#local .loss-session--next .loss-ref-label").text_content())
    ok("ES break label","no se trasladó" in q.locator("#local .loss-link").get_attribute("aria-label").lower())
    ok("ES no memory claim","memoria" not in q.locator("#local").text_content().lower())
    ok("ES one close",q.locator("#local .loss-verdict,#local .loss-cost,#local .loss-bridge,#local .loss-seam,#local .loss-ghost").count()==0)
    ok("ES human close","volver a explicarlo" in q.locator("#local .loss-stakes").text_content())
    ok("ES failure is second section",q.locator("main > section").nth(1).get_attribute("id")=="failures")
    ok("ES failure five modes",q.locator("#failures .failure-case").count()==5)
    ok("ES failure H2","cinco formas" in q.locator("#failures h2").text_content())
    ok("ES failure lead","contexto ganado" in q.locator("#failures .failure-lead").text_content())
    ok("ES failure close","El resultado puede sobrevivir" in q.locator("#failures .failure-close").text_content() and "no siempre" in q.locator("#failures .failure-close").text_content())
    ok("ES failure mechanisms",q.locator("#failures .case-mech").evaluate_all("els=>els.map(e=>e.textContent.trim())")==["Interpretación","Reconstrucción","Compresión","Transferencia","Recuperación"])
    ctx.close()
    ctx=b.new_context(viewport={"width":1200,"height":900},java_script_enabled=False); q=ctx.new_page(); q.goto(BASE+"/",wait_until="load")
    ok("no-JS closure readable","criteria remain available" in q.locator("#next").text_content()); ctx.close()
    p.emulate_media(media="print"); p.wait_for_timeout(600)
    ok("print closure visible",p.locator("#next .home-closure__label").first.is_visible())
    b.close()
print("\n".join(results)); print("----"); print("TOTAL",len(results),"FAILURES",len(failures)); sys.exit(1 if failures else 0)
